import { describe, it, expect } from 'vitest';
import { filterByRange } from './filter';

describe('filterByRange', () => {
  it('incluye exports dentro del rango', () => {
    expect(filterByRange([{ fecha: '2026-08-10' }], '2026-08-01', '2026-08-31')).toHaveLength(1);
  });

  it.skip('excluye exports con fecha inválida', () => {
    expect(filterByRange([{ fecha: 'no-es-fecha' }], '2026-08-01', '2026-08-31')).toHaveLength(0);
  });
});
